export const MATH_DIGIT_IDS = ['pi', 'phi', 'e', 'sqrt2'] as const

export type MathDigitId = (typeof MATH_DIGIT_IDS)[number]

export const MATH_DIGIT_MILESTONES = [10, 25, 50, 100, 200, 500, 1000] as const

export type MathDigitMilestone = (typeof MATH_DIGIT_MILESTONES)[number]

export type MathDigit = {
  id: MathDigitId
  symbol: string
  /** Integer part plus the decimal point, shown and not typed. */
  head: string
  /** One thousand digits after the decimal point. */
  digits: string
}

export const MATH_DIGITS: readonly MathDigit[] = [
  {
    id: 'pi',
    symbol: 'π',
    head: '3.',
    digits:
      '',
  },
  {
    id: 'phi',
    symbol: 'φ',
    head: '1.',
    digits:
      '',
  },
  {
    id: 'e',
    symbol: 'e',
    head: '2.',
    digits:
      '',
  },
  {
    id: 'sqrt2',
    symbol: '√2',
    head: '1.',
    digits:
      '',
  },
]

export function mathDigitById(id: MathDigitId): MathDigit {
  const item = MATH_DIGITS.find((digit) => digit.id === id)
  if (!item) throw new Error(`Unknown constant ${id}`)
  return item
}
